*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
scwin.vScrenID = 'ULDSTF37701.xml';
scwin.gSeq;
scwin.gIsurCd;
scwin.gActTpCd;
scwin.gChgBfafTpCd;
scwin.gApprovStatCd;
scwin.regMode;
scwin.gEmpNo = js_emp_no;
scwin.gDepCd = js_dep_cd;
scwin.gDutyGrp = js_gduty;
scwin.gDutyYn = js_duty;
scwin.gDutyChrg = js_duty_chrg; // 세션정보 	
scwin.gJobTitle = js_jobtitl;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // 팀장  : 09,  부서장: 40,  팀원: 03


//부모창에서 필요변수 저장
scwin.fn_GetParentValue = function() {
    scwin.regMode = frame.opener.scwin.regMode;
    if (scwin.regMode == "REG") {
        scwin.gSeq = "0";
        scwin.gApprovStatCd = "10";
        $c.stf.setObjectValue(txb_approv_stat_cd, scwin.gApprovStatCd);
    } else {
        scwin.gSeq = frame.opener.scwin.gSeq;
    }
    scwin.gIsurCd = frame.opener.scwin.gIsurCd;
    gComAbbrv = frame.opener.gComAbbrv;
    scwin.gActTpCd = frame.opener.scwin.gActTpCd;
    $c.stf.setObjectValue(txb_seq, scwin.gSeq);
    $c.stf.setObjectValue(txb_isur_cd, scwin.gIsurCd);
    $c.stf.setObjectValue(txb_com_abbrv, gComAbbrv);
    $c.stf.setObjectValue(txb_act_tp_cd, scwin.gActTpCd);
};



// 버튼 권한 체크
scwin.fn_getProcsTeamCheck = function() {
    var url = "/ConfrmProcs.do?method=getProcsTeamCheck" + "&inputMessageId=CONFRM_PROCS_CHK_PROCS_TEAM_OUT" + "&outputMessageId=CONFRM_PROCS_CHK_PROCS_TEAM_OUT" + "&ISUR_CD=" + scwin.gIsurCd;
    dts_btnshow.DataID = encodeURI(url);
    dts_btnshow.reset();
};


// 버튼 권한 체크
// panel_proc_1 : 검토, 삭제, 저장
// panel_proc_2 : 승인, 유보
// panel_proc_3 : 달력,  사유추가, 사유삭제
scwin.fn_showProcButton = function(pDepCd, pEmpNo) {
    // 팀장, 당번팀장, 당번인 경우
    if (scwin.gJobTitle == '09' || scwin.gDutyYn == 'Y' || scwin.gDutyChrg == 'Y') {
        // 검토, 삭제, 수정 처리
        if (scwin.regMode == 'MOD') {
            btn_Save.src = "../img/btn_modify.gif";
            $c.stf.showObj(panel_proc_2, false);
            // 승인, 유보 처리

        } else if (scwin.regMode == 'APP') {
            $c.stf.showObj(panel_proc_1, false);
            $c.stf.showObj(panel_proc_3, false);
            edt_strt_dd.setReadOnly(true);
            txa_remk.setReadOnly(true);
            // 상세 화면 버튼은 모두 안보이게 처리		

        } else if (scwin.regMode == 'VIEW') {
            $c.stf.showObj(panel_proc_1, false);
            $c.stf.showObj(panel_proc_2, false);
            $c.stf.showObj(panel_proc_3, false);
            edt_strt_dd.setReadOnly(true);
            txa_remk.setReadOnly(true);
        } else {
            $c.stf.showObj(btn_Review, false);
            $c.stf.showObj(btn_Del, false);
            $c.stf.showObj(panel_proc_2, false);
            // 지정해제는 사유추가 불가
            if ($c.stf.getObjectValue(txb_act_tp_cd) == '3') {
                $c.stf.showObj(btn_rsn_add, false);
                $c.stf.showObj(btn_rsn_del, false);
            }
        }

        // 팀원이고 같은 팀인 경우	

    } else if (scwin.gJobTitle == '03' && scwin.gDepCd == pDepCd) {
        // 검토, 삭제, 수정 처리
        if (scwin.regMode == 'MOD') {
            btn_Save.src = "../img/btn_modify.gif";
            $c.stf.showObj(panel_proc_2, false);
            // 승인, 유보 처리

        } else if (scwin.regMode == 'APP') {
            $c.stf.showObj(panel_proc_1, false);
            $c.stf.showObj(panel_proc_2, false);
            $c.stf.showObj(panel_proc_3, false);
            edt_strt_dd.setReadOnly(true);
            txa_remk.setReadOnly(true);
            // 상세 화면 버튼은 모두 안보이게 처리	

        } else if (scwin.regMode == 'VIEW') {
            $c.stf.showObj(panel_proc_1, false);
            $c.stf.showObj(panel_proc_2, false);
            $c.stf.showObj(panel_proc_3, false);
            edt_strt_dd.setReadOnly(true);
            txa_remk.setReadOnly(true);
        } else {
            $c.stf.showObj(btn_Review, false);
            $c.stf.showObj(btn_Del, false);
            $c.stf.showObj(panel_proc_2, false);
            // 지정해제는 사유추가 불가
            if ($c.stf.getObjectValue(txb_act_tp_cd) == '3') {
                $c.stf.showObj(btn_rsn_add, false);
                $c.stf.showObj(btn_rsn_del, false);
            }
        }
    } else {
        $c.stf.showObj(panel_proc_1, false);
        $c.stf.showObj(panel_proc_2, false);
        $c.stf.showObj(panel_proc_3, false);
        edt_strt_dd.setReadOnly(true);
        txa_remk.setReadOnly(true);
    }
};
scwin.fn_SetInfoHeader = function() {
    dts_info_design.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=CONFRM_PROCS_DESIGN_EXCLUDE_SECU_LIST";
    dts_info_design.reset();
    dts_info_design.insertRow();
};
scwin.fn_SetlistHeader = function() {
    dts_list_design.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=CONFRM_PROCS_DESIGN_RSN";
    dts_list_design.reset();
    //dts_list_design.AddRow();

};
scwin.fn_SetValue = function() {
    if ($c.stf.getObjectValue(txb_act_tp_cd) == '3') {
        $c.stf.setObjectValue(txb_chg_bfaf_tp_cd, '2'); //변경전

    } else {
        $c.stf.setObjectValue(txb_chg_bfaf_tp_cd, '2'); //변경후

    }
};



//상세 정보
scwin.fn_ReadInfo = function() {
    var url = "/ConfrmProcs.do?method=readDesignInfo" + "&inputMessageId=CONFRM_PROCS_DESIGN_INFO" + "&CPOC_SEQ=" + scwin.gSeq + "&ISUR_CD=" + scwin.gIsurCd + "&CPOC_ACT_TP_CD=" + scwin.gActTpCd + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_info_design.DataID = encodeURI(url);
    dts_info_design.reset();
};



// 지정사유 목록		   
scwin.fn_ReadList = function() {
    var url_list = "/ConfrmProcs.do?method=readDesignList" + "&inputMessageId=CONFRM_PROCS_DESIGN_LIST" + "&outputMessageId=CONFRM_PROCS_DESIGN_LIST" + "&CPOC_SEQ=" + scwin.gSeq + "&CPOC_CHG_BFAF_TP_CD=" + $c.stf.getObjectValue(txb_chg_bfaf_tp_cd) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // 그리드의 데이타 조회
    dts_list_design.DataID = encodeURI(url_list);
    dts_list_design.reset();
    //ShowWin(grd_Grid);

};




// 변경전 지정사유 목록
scwin.fn_ReadBeforeList = function() {
    var url_list = "/ConfrmProcs.do?method=readBeforeDesignList" + "&inputMessageId=CONFRM_PROCS_DESIGN_LIST" + "&outputMessageId=CONFRM_PROCS_DESIGN_LIST" + "&ISUR_CD=" + scwin.gIsurCd + "&CPOC_CHG_BFAF_TP_CD=" + $c.stf.getObjectValue(txb_chg_bfaf_tp_cd) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // 그리드의 데이타 조회
    dts_list_design.DataID = encodeURI(url_list);
    dts_list_design.reset();
    //ShowWin(grd_Grid);

};





//등록 및 수정 처리
scwin.fn_Procs = function() {
    var vStrt_dd = $c.stf.getObjectValue(edt_strt_dd);
    if (vStrt_dd == '') {
        $c.win.alert("지정일을 선택하세요.");
        edt_strt_dd.focus();
        return;
    }
    if (vStrt_dd <= $c.ut.cGetToday("yyyymmdd")) {
        $c.win.alert("지정일을 오늘 날짜 이후로 지정하세요.");
        edt_strt_dd.focus();
        return;
    }

    // 매매일 체크
    if (!$c.lc.fn_TrHoldyYn(dts_checkDD, vStrt_dd)) {
        edt_strt_dd.focus();
        return;
    }

    // 지정일 체크
    if (scwin.fn_checkEnforceDD(scwin.gIsurCd, vStrt_dd) == false) {
        edt_strt_dd.focus();
        return;
    }
    if (dts_list_design.getTotalRow() < 1) {
        $c.win.alert("지정사유를 선택하세요.");
        return;
    }
    var tmpStr;
    var vMethod;
    if (scwin.regMode == 'REG') {
        tmpStr = "저장 하시겠습니까?";
        vMethod = "insertConfrmProcsObjCorp";
    } else if (scwin.regMode == 'MOD') {
        tmpStr = "수정 하시겠습니까?";
        vMethod = "updateConfrmProcsObjCorp";
    }
    var vAnswer = confirm(tmpStr);
    if (vAnswer == true) {
        trs_insert.Action = "/ConfrmProcs.do?method=" + vMethod + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_insert.KeyName = "toinb_dataid4";
        trs_insert.KeyValue = "JSP(I:pInput1=dts_info_design,I:pInput2=dts_list_design)";
        trs_insert.Post();
    }
};






//승인상태 처리
scwin.fn_approvStatProcs = function(gbn) {
    var tmpStr;
    var vMethod;
    vMethod = "updateApprovStatCd";
    if (gbn == '20') {
        tmpStr = "검토 하시겠습니까?";
    } else if (gbn == '30') {
        tmpStr = "승인 하시겠습니까?";
    } else if (gbn == '40') {
        tmpStr = "유보 하시겠습니까?";
    }


    // 유보일 경우 접수 상태로 변경한다.
    if (gbn == '40') {
        $c.stf.setObjectValue(txb_approv_stat_cd, "10");
    } else {
        $c.stf.setObjectValue(txb_approv_stat_cd, gbn);
    }
    var vAnswer = confirm(tmpStr);
    if (vAnswer == true) {
        trs_approvUpdate.Action = "/ConfrmProcs.do?method=" + vMethod + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_approvUpdate.KeyName = "toinb_dataid4";
        trs_approvUpdate.KeyValue = "JSP(I:pInput1=dts_info_design)";
        trs_approvUpdate.Post();
    }
};




//삭제
scwin.fn_delete = function() {
    var tmpStr;
    var vMethod;
    vMethod = "deleteConfrmProcsObjCorp";
    tmpStr = "삭제 하시겠습니까?";
    var vAnswer = confirm(tmpStr);
    if (vAnswer == true) {
        trs_delete.Action = "/ConfrmProcs.do?method=" + vMethod + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_delete.KeyName = "toinb_dataid4";
        trs_delete.KeyValue = "JSP(I:pInput1=dts_info_design)";
        trs_delete.Post();
    }
};
scwin.fn_openDesignRsn = async function() {
    await $c.frame.CreateDialogFrame("wndDiscls", "/dsclmgt/ULDSTF37703.gfm", "지정사유", 200, 200, 10, 20, "window");
};
scwin.fn_SetParRsnCd = function(arrPar) {
    //선택된 사유코드 중복체크
    if (!$c.lc.fn_isNewValueForDataSet(dts_list_design, "CPOC_DESIGN_RSN_CD", arrPar[0])) return;
    dts_list_design.insertRow();
    dts_list_design.setCellData(dts_list_design.getRowPosition(), "CPOC_DESIGN_RSN_CD", arrPar[0]);
    dts_list_design.setCellData(dts_list_design.getRowPosition(), "CPOC_DESIGN_RSN_NM", arrPar[1]);
    dts_list_design.sort("CPOC_DESIGN_RSN_CD", 0);
    //dts_list_design.sort(); // W-Craft 주석처리 

};
scwin.parent_function_call = function() {
    var parentWin = $c.frame.path("../");
    parentWin.fn_Search();
};


// 지정일 체크
scwin.fn_checkEnforceDD = function(pIsurCd, pStrt_dd) {
    var vENFORCE_DD;
    dts_checkDD.DataID = encodeURI("/ConfrmProcs.do?method=checkEnforceDD&outputMessageId=CONFRM_PROCS_CHK_ENFORCE_DD_OUT&ISUR_CD=" + pIsurCd + "&CPOC_ENFORCE_DD=" + pStrt_dd);
    dts_checkDD.Reset();
    vENFORCE_DD = dts_checkDD.getCellData(1, "CPOC_ENFORCE_DD");

    // 지정가능한 날짜가 있으면 
    if (vENFORCE_DD == undefined) {
        return true;
        // 수정 화면에서 저장된 날짜와 같으면	
    } else if ($c.stf.getObjectValue(txb_chk_date) == pStrt_dd) {
        return true;
        // 입력한 일자가 같은 날짜에 있으면
    } else if (vENFORCE_DD == pStrt_dd) {
        $c.win.alert("입력한 일자에 예정된 확인절차 대상법인 처리 업무가 있습니다.");
        return false;
        // 입력한 일자가 이후 날짜에 있으면
    } else {
        $c.win.alert("입력한 일자 이후에 예정된 확인절차 대상법인 처리 업무가 있습니다.");
        return false;
    }
    return true;
};
scwin.dts_list_design_OnLoadCompleted = function(rowcount) {
    //FillGridHeaderTotalCnt(rowcount, panel_page);	

};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_info_design_OnLoadCompleted = function(rowcount) {

};
scwin.trs_insert_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "등록"));
    scwin.parent_function_call();
    await $c.frame.CloseFrame();
};
scwin.trs_insert_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "등록"));
    $c.win.alert(trs_insert.ErrorMsg);
};
scwin.trs_approvUpdate_OnSuccess = async function() {
    $c.win.alert("처리 성공하였습니다.");
    scwin.parent_function_call();
    await $c.frame.CloseFrame();
};
scwin.trs_approvUpdate_OnFail = function() {
    $c.win.alert("처리 실패하였습니다.");
    $c.win.alert(trs_insert.ErrorMsg);
};
scwin.trs_delete_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    scwin.parent_function_call();
    await $c.frame.CloseFrame();
};
scwin.trs_delete_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
    $c.win.alert(trs_insert.ErrorMsg);
};
scwin.img_cls_dd_onclick = function() {
    popUpCalendar2(edt_strt_dd);
};
scwin.btn_rsn_del_onclick = function() {
    $c.cp.removeRow(dts_list_design, dts_list_design.getRowPosition());
};
scwin.btn_rsn_add_onclick = function() {
    fn_SetPar = fn_SetParRsnCd;
    scwin.fn_openDesignRsn();
};
scwin.btn_Review_onclick = function() {
    scwin.fn_approvStatProcs('20');
};
scwin.btn_Del_onclick = function() {
    scwin.fn_delete();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Procs();
};
scwin.btn_Approv_onclick = function() {
    scwin.fn_approvStatProcs('30');
};
scwin.btn_Resv_onclick = function() {
    scwin.fn_approvStatProcs('40');
};
scwin.dts_btnshow_OnLoadCompleted = function(rowcount) {
    scwin.fn_showProcButton(dts_btnshow.getCellData(1, "DEP_CD"), dts_btnshow.getCellData(1, "EMP_NO"));
};
scwin.dts_btnshow_OnLoadError = function() {
    $c.win.alert('dts_btnshow.OnFail() :' + dts_btnshow.ErrorMsg);
};
scwin.gform_onload = function() {
    // 패널라운드 처리

    $c.stf.showObj(txb_chk_date, false);
    $c.stf.showObj(txb_seq, false);
    $c.stf.showObj(txb_act_tp_cd, false);
    $c.stf.showObj(txb_approv_stat_cd, false);
    $c.stf.showObj(txb_emp_no, false);
    $c.stf.showObj(txb_chg_bfaf_tp_cd, false);
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    scwin.fn_GetParentValue();
    scwin.fn_getProcsTeamCheck();
    scwin.fn_SetValue();
    if (scwin.regMode == 'REG') {
        scwin.fn_SetInfoHeader();
        scwin.fn_GetParentValue();
        scwin.fn_SetlistHeader();
        scwin.fn_SetValue();
        if (scwin.gActTpCd == '3') {
            $c.stf.setObjectValue(txb_chg_bfaf_tp_cd, '2');
            scwin.fn_ReadBeforeList();
        }
    } else if (scwin.regMode == 'MOD') {
        scwin.fn_SetlistHeader();
        scwin.fn_ReadInfo(); //기본정보 불러오기
        scwin.fn_SetValue();
        if (scwin.gActTpCd == '3') {
            scwin.fn_ReadBeforeList();
        } else {
            scwin.fn_ReadList();
        }
        $c.stf.setObjectValue(txb_chk_date, $c.stf.getObjectValue(edt_strt_dd));
    } else if (scwin.regMode == 'APP') {
        scwin.fn_SetlistHeader();
        scwin.fn_ReadInfo(); //기본정보 불러오기
        scwin.fn_SetValue();
        if (scwin.gActTpCd == '3') {
            scwin.fn_ReadBeforeList();
        } else {
            scwin.fn_ReadList();
        }
    } else {
        scwin.fn_SetlistHeader();
        scwin.fn_ReadInfo(); //기본정보 불러오기
        scwin.fn_SetValue();
        if (scwin.gActTpCd == '3') {
            scwin.fn_ReadBeforeList();
        } else {
            scwin.fn_ReadList();
        }
    }
    $c.stf.setObjectValue(txb_emp_no, scwin.gEmpNo);
    if ($c.stf.getObjectValue(txb_act_tp_cd) == '3') {
        $c.stf.showObj(lbl_tmp_5, false);
        //showObj(lbl_tmp_6, true);

    } else {
        //showObj(lbl_tmp_5, false);

    }
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_01);
};
